CREATE FUNCTION photo.billing_ensure_profile(p_tenant uuid,p_plan_version_id uuid,p_key text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_subject uuid;
BEGIN
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_TENANT_INACTIVE' USING ERRCODE='P0001'; END IF;
 SELECT financial_subject_id INTO v_subject FROM tenant_billing_profiles WHERE tenant_id=p_tenant;
 IF FOUND THEN RETURN v_subject; END IF;
 IF p_plan_version_id IS NULL THEN RAISE EXCEPTION 'BILLING_PLAN_VERSION_REQUIRED' USING ERRCODE='P0001'; END IF;
 v_subject := gen_random_uuid();
 INSERT INTO billing_contacts(financial_subject_id,status,encryption_key_ref)
  VALUES(v_subject,'active','key:bootstrap');
 INSERT INTO tenant_billing_profiles(tenant_id,financial_subject_id,current_plan_version_id,billing_mode,lifecycle,lifecycle_epoch,entitlement_revision)
  VALUES(p_tenant,v_subject,p_plan_version_id,'trial','active',1,1);
 RETURN v_subject;
END $$;

CREATE FUNCTION photo.billing_create_quote(p_tenant uuid,p_actor uuid,p_kind text,p_selection jsonb,p_selection_hash bytea,p_net bigint,p_tax bigint,p_gross bigint,p_currency text,p_tax_policy text,p_key text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_id uuid; v_revision bigint; v_old uuid;
BEGIN
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_TENANT_INACTIVE' USING ERRCODE='P0001'; END IF;
 SELECT id INTO v_old FROM billing_quotes WHERE tenant_id=p_tenant AND request_hash=p_selection_hash;
 IF FOUND THEN RETURN v_old; END IF;
 IF p_net IS NULL OR p_net<0 OR p_tax IS NULL OR p_tax<0 OR p_gross IS NULL OR p_gross<0
  THEN RAISE EXCEPTION 'BILLING_QUOTE_AMOUNT_INVALID' USING ERRCODE='P0001'; END IF;
 IF p_kind NOT IN ('subscription','topup','operation_topup','upgrade','storage','egress')
  THEN RAISE EXCEPTION 'BILLING_QUOTE_KIND_INVALID' USING ERRCODE='P0001'; END IF;
 SELECT entitlement_revision INTO v_revision FROM tenant_billing_profiles WHERE tenant_id=p_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PROFILE_MISSING' USING ERRCODE='P0001'; END IF;
 v_id := gen_random_uuid();
 INSERT INTO billing_quotes(id,tenant_id,actor_id,kind,plan_revision,resource_snapshot,resource_snapshot_hash,net_minor,tax_minor,gross_minor,currency,tax_policy_version,expires_at,request_hash)
  VALUES(v_id,p_tenant,p_actor,p_kind,v_revision,p_selection,p_selection_hash,p_net,p_tax,p_gross,p_currency,p_tax_policy,clock_timestamp()+INTERVAL'15 minutes',p_selection_hash);
 RETURN v_id;
END $$;

