CREATE FUNCTION photo.billing_accept_quote(p_quote_id uuid,p_actor uuid,p_key text,p_hash bytea) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE q billing_quotes%ROWTYPE; v_id uuid; v_old uuid;
BEGIN
 SELECT * INTO q FROM billing_quotes WHERE id=p_quote_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_QUOTE_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF q.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'BILLING_QUOTE_EXPIRED' USING ERRCODE='P0001'; END IF;
 IF q.resource_snapshot_hash<>p_hash THEN RAISE EXCEPTION 'BILLING_QUOTE_HASH_MISMATCH' USING ERRCODE='P0001'; END IF;
 PERFORM 1 FROM tenant_billing_profiles WHERE tenant_id=q.tenant_id AND lifecycle='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PROFILE_NOT_ACTIVE' USING ERRCODE='P0001'; END IF;
 SELECT id INTO v_old FROM billing_orders WHERE tenant_id=q.tenant_id AND idempotency_key=p_key;
 IF FOUND THEN RETURN v_old; END IF;
 v_id := gen_random_uuid();
 INSERT INTO billing_orders(id,tenant_id,quote_id,kind,state,net_minor,tax_minor,gross_minor,currency,idempotency_key,request_hash)
  VALUES(v_id,q.tenant_id,p_quote_id,q.kind,'created',q.net_minor,q.tax_minor,q.gross_minor,q.currency,p_key,p_hash);
 UPDATE billing_quotes SET accepted_at=clock_timestamp() WHERE id=p_quote_id;
 RETURN v_id;
END $$;

CREATE FUNCTION photo.billing_request_change(p_tenant uuid,p_quote_id uuid,p_expected_revision bigint,p_key text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE q billing_quotes%ROWTYPE; v_id uuid; v_old uuid; v_revision bigint; v_sub uuid;
BEGIN
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_TENANT_INACTIVE' USING ERRCODE='P0001'; END IF;
 SELECT entitlement_revision INTO v_revision FROM tenant_billing_profiles WHERE tenant_id=p_tenant AND lifecycle='active' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PROFILE_NOT_ACTIVE' USING ERRCODE='P0001'; END IF;
 IF v_revision<>p_expected_revision THEN RAISE EXCEPTION 'BILLING_REVISION_CONFLICT' USING ERRCODE='P0001'; END IF;
 SELECT * INTO q FROM billing_quotes WHERE id=p_quote_id AND tenant_id=p_tenant FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_QUOTE_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF q.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'BILLING_QUOTE_EXPIRED' USING ERRCODE='P0001'; END IF;
 SELECT id INTO v_old FROM billing_change_requests WHERE tenant_id=p_tenant AND idempotency_key=p_key;
 IF FOUND THEN RETURN v_old; END IF;
 SELECT id INTO v_sub FROM billing_subscriptions WHERE tenant_id=p_tenant AND state='active' LIMIT 1;
 PERFORM 1 FROM billing_change_requests WHERE tenant_id=p_tenant AND state NOT IN ('applied','failed','canceled');
 IF FOUND THEN RAISE EXCEPTION 'BILLING_CHANGE_ALREADY_PENDING' USING ERRCODE='P0001'; END IF;
 v_id := gen_random_uuid();
 INSERT INTO billing_change_requests(id,tenant_id,subscription_id,change_type,quote_id,effective_at,idempotency_key,request_hash,state)
  VALUES(v_id,p_tenant,v_sub,q.kind,p_quote_id,clock_timestamp(),p_key,q.resource_snapshot_hash,'quoted');
 RETURN v_id;
END $$;

CREATE FUNCTION photo.billing_attach_checkout(p_order_id uuid,p_session_snapshot jsonb,p_operation_key text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE o billing_orders%ROWTYPE;
BEGIN
 SELECT * INTO o FROM billing_orders WHERE id=p_order_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_ORDER_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF o.state NOT IN ('created','checkout_pending') THEN RAISE EXCEPTION 'BILLING_ORDER_STATE_INVALID' USING ERRCODE='P0001'; END IF;
 IF o.provider_checkout_id IS NOT NULL AND o.provider_checkout_id<>(p_session_snapshot->>'id')::text
  THEN RAISE EXCEPTION 'BILLING_CHECKOUT_SESSION_CONFLICT' USING ERRCODE='P0001'; END IF;
 UPDATE billing_orders SET state='checkout_pending',provider_checkout_id=(p_session_snapshot->>'id')::text WHERE id=p_order_id;
END $$;

CREATE FUNCTION photo.billing_apply_paid_upgrade(p_change_id uuid,p_allocation_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE cr billing_change_requests%ROWTYPE;
BEGIN
 SELECT * INTO cr FROM billing_change_requests WHERE id=p_change_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_CHANGE_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF cr.state='applied' THEN RETURN; END IF;
 IF cr.state<>'paid' THEN RAISE EXCEPTION 'BILLING_CHANGE_STATE_INVALID' USING ERRCODE='P0001'; END IF;
 UPDATE billing_change_requests SET state='applying' WHERE id=p_change_id;
 UPDATE billing_invoice_allocations SET state='applied' WHERE id=p_allocation_id AND state='pending';
 UPDATE tenant_billing_profiles SET entitlement_revision=entitlement_revision+1 WHERE tenant_id=cr.tenant_id;
 UPDATE billing_change_requests SET state='applied' WHERE id=p_change_id;
END $$;

CREATE FUNCTION photo.billing_apply_refund(p_refund_id uuid,p_verified_hash bytea) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE r billing_refunds%ROWTYPE; p billing_payments%ROWTYPE;
BEGIN
 SELECT * INTO r FROM billing_refunds WHERE id=p_refund_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_REFUND_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF r.state='succeeded' THEN RETURN; END IF;
 IF r.state<>'pending' THEN RAISE EXCEPTION 'BILLING_REFUND_STATE_INVALID' USING ERRCODE='P0001'; END IF;
 SELECT * INTO p FROM billing_payments WHERE id=r.payment_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PAYMENT_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 IF p.refunded_minor+r.amount_minor>p.amount_minor
  THEN RAISE EXCEPTION 'BILLING_REFUND_EXCEEDS_PAYMENT' USING ERRCODE='P0001'; END IF;
 UPDATE billing_payments SET refunded_minor=refunded_minor+r.amount_minor WHERE id=r.payment_id;
 UPDATE billing_refunds SET state='succeeded' WHERE id=p_refund_id;
END $$;

CREATE FUNCTION photo.billing_assign_custom(p_tenant uuid,p_assignment_data jsonb,p_actor uuid,p_reason text,p_key text) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_id uuid; v_old uuid; v_plan_version_id uuid; v_amount bigint; v_currency text; v_mode text; v_starts timestamptz; v_ends timestamptz;
BEGIN
 PERFORM 1 FROM photo.tenants WHERE id=p_tenant AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_TENANT_INACTIVE' USING ERRCODE='P0001'; END IF;
 PERFORM 1 FROM tenant_billing_profiles WHERE tenant_id=p_tenant AND lifecycle='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PROFILE_NOT_ACTIVE' USING ERRCODE='P0001'; END IF;
 v_plan_version_id := (p_assignment_data->>'plan_version_id')::uuid;
 v_amount         := (p_assignment_data->>'amount_net_minor')::bigint;
 v_currency       := (p_assignment_data->>'currency')::text;
 v_mode           := coalesce(p_assignment_data->>'billing_mode','manual');
 v_starts         := (p_assignment_data->>'starts_at')::timestamptz;
 v_ends           := (p_assignment_data->>'ends_at')::timestamptz;
 IF v_plan_version_id IS NULL OR v_amount IS NULL OR v_currency IS NULL OR v_starts IS NULL OR v_ends IS NULL
  THEN RAISE EXCEPTION 'BILLING_ASSIGNMENT_DATA_INCOMPLETE' USING ERRCODE='P0001'; END IF;
 IF v_ends<=v_starts THEN RAISE EXCEPTION 'BILLING_ASSIGNMENT_DATE_INVALID' USING ERRCODE='P0001'; END IF;
 IF v_amount<0 THEN RAISE EXCEPTION 'BILLING_ASSIGNMENT_AMOUNT_NEGATIVE' USING ERRCODE='P0001'; END IF;
 PERFORM 1 FROM billing_custom_assignments WHERE tenant_id=p_tenant AND state='active'
  AND starts_at<v_ends AND ends_at>v_starts;
 IF FOUND THEN RAISE EXCEPTION 'BILLING_ASSIGNMENT_OVERLAP' USING ERRCODE='P0001'; END IF;
 SELECT id INTO v_old FROM billing_custom_assignments WHERE tenant_id=p_tenant AND reason=p_key AND state='draft';
 IF FOUND THEN RETURN v_old; END IF;
 v_id := gen_random_uuid();
 INSERT INTO billing_custom_assignments(id,tenant_id,custom_plan_version_id,amount_net_minor,currency,billing_mode,starts_at,ends_at,state,reason,assigned_by)
  VALUES(v_id,p_tenant,v_plan_version_id,v_amount,v_currency,v_mode,v_starts,v_ends,'draft',p_reason,p_actor);
 RETURN v_id;
END $$;

CREATE FUNCTION photo.billing_bind_provider_price(p_account_id uuid,p_local_target uuid,p_snapshot_hash bytea) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_id uuid; v_old uuid;
BEGIN
 IF p_account_id IS NULL OR p_local_target IS NULL OR p_snapshot_hash IS NULL
  THEN RAISE EXCEPTION 'BILLING_BIND_INPUT_INCOMPLETE' USING ERRCODE='P0001'; END IF;
 SELECT id INTO v_old FROM billing_order_lines WHERE provider_price_binding_id=p_local_target LIMIT 1;
 IF FOUND THEN RETURN v_old; END IF;
 v_id := gen_random_uuid();
 INSERT INTO billing_order_lines(id,tenant_id,order_id,ordinal,resource_code,pack_count,unit_net_minor,net_minor,tax_minor,gross_minor,currency,resource_quantity,included_egress_bytes,expiry_policy,snapshot,provider_price_binding_id)
  SELECT v_id,q.tenant_id,q.id,0,'standard_photo',1,q.net_minor,q.net_minor,q.tax_minor,q.gross_minor,q.currency,1,0,'none','{}',p_local_target
  FROM billing_quotes q WHERE q.id=p_local_target LIMIT 1;
 RETURN v_id;
END $$;

CREATE FUNCTION photo.billing_publish_plan_version(p_version_id uuid,p_expected_revision bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,photo AS $$
DECLARE v_revision bigint;
BEGIN
 IF p_version_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision<1
  THEN RAISE EXCEPTION 'BILLING_PUBLISH_INPUT_INVALID' USING ERRCODE='P0001'; END IF;
 PERFORM 1 FROM photo.billing_plan_versions WHERE id=p_version_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_PLAN_VERSION_NOT_FOUND' USING ERRCODE='P0001'; END IF;
 UPDATE photo.billing_plan_versions SET is_published=true,published_at=clock_timestamp()
  WHERE id=p_version_id AND NOT is_published;
END $$;
